WEAK_OPENERS = ("helped", "worked on", "responsible for", "participated in", "assisted")
STRONG_VERBS = ("built", "designed", "implemented", "automated", "reduced", "cut",
                "migrated", "optimized", "wrote", "shipped", "led", "created", "debugged")

bullets = [
    "Worked on the backend for a club app.",
    "Built a Flask REST API for a club events app, serving 400+ members.",
    "Responsible for testing.",
    # Paste your own bullets here, then run again
]

for b in bullets:
    text = b.lower()
    problems = []
    if text.startswith(WEAK_OPENERS):
        problems.append("weak opener: say what you built or changed")
    elif not text.startswith(STRONG_VERBS):
        problems.append("check the first word: is it a strong action verb?")
    if not any(ch.isdigit() for ch in b):
        problems.append("no number: can you measure the result?")
    if len(b) > 160:
        problems.append("long: aim for one or two lines")
    print("FIX" if problems else "OK ", b)
    for p in problems:
        print("     -", p)
